36	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
37	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Syntactic check for an email address: a non-empty local part, an {@code @}, and a domain with
65	     * at least one dot and no whitespace on either side.
66	     */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        validateRequiredFields(ownerFieldsDto);
117	        normalizeTelephone(ownerFieldsDto);
118	        rejectDuplicateTelephone(ownerFieldsDto);
119	        rejectDuplicateHousehold(ownerFieldsDto);
120	        normalizeEmail(ownerFieldsDto);
121	        defaultRegistrationDate(ownerFieldsDto);
122	        HttpHeaders headers = new HttpHeaders();
123	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
124	        assignCustomerCode(owner);
125	        this.clinicService.saveOwner(owner);
126	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
127	        headers.setLocation(UriComponentsBuilder.newInstance()
128	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
129	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
135	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
136	        if (currentOwner == null) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        currentOwner.setAddress(ownerFieldsDto.getAddress());
140	        currentOwner.setCity(ownerFieldsDto.getCity());
141	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
142	        currentOwner.setLastName(ownerFieldsDto.getLastName());
143	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
144	        normalizeEmail(ownerFieldsDto);
145	        currentOwner.setEmail(ownerFieldsDto.getEmail());
146	        this.clinicService.saveOwner(currentOwner);
147	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Transactional
152	    @Override
153	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
154	        Owner owner = this.clinicService.findOwnerById(ownerId);
155	        if (owner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        this.clinicService.deleteOwner(owner);
159	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
165	        Owner owner = this.clinicService.findOwnerById(ownerId);
166	        if (owner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        HttpHeaders headers = new HttpHeaders();
170	        Pet pet = petMapper.toPet(petFieldsDto);
171	        owner.setId(ownerId);
172	        pet.setOwner(owner);
173	        pet.getType().setName(null);
174	        this.clinicService.savePet(pet);
175	        PetDto petDto = petMapper.toPetDto(pet);
176	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
177	            .buildAndExpand(pet.getId()).toUri());
178	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
184	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
185	        if (currentOwner != null) {
186	            Pet currentPet = this.clinicService.findPetById(petId);
187	            if (currentPet != null) {
188	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
189	                currentPet.setName(petFieldsDto.getName());
190	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
191	                this.clinicService.savePet(currentPet);
192	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
193	            }
194	        }
195	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
201	        HttpHeaders headers = new HttpHeaders();
202	        Visit visit = visitMapper.toVisit(visitFieldsDto);
203	        Pet pet = new Pet();
204	        pet.setId(petId);
205	        visit.setPet(pet);
206	        this.clinicService.saveVisit(visit);
207	        VisitDto visitDto = visitMapper.toVisitDto(visit);
208	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
209	            .buildAndExpand(visit.getId()).toUri());
210	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
211	    }
212	
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
217	        Owner owner = this.clinicService.findOwnerById(ownerId);
218	        if (owner != null) {
219	            Pet pet = owner.getPet(petId);
220	            if (pet != null) {
221	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
222	            }
223	        }
224	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
225	    }
226	
227	    /**
228	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
229	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
230	     * does not catch). The names of all offending fields are collected so the caller receives a
231	     * 400 response whose {@code errors} array lists each one.
232	     */
233	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
234	        List<String> missingFields = new ArrayList<>();
235	        if (isBlank(ownerFieldsDto.getFirstName())) {
236	            missingFields.add("firstName");
237	        }
238	        if (isBlank(ownerFieldsDto.getLastName())) {
239	            missingFields.add("lastName");
240	        }
241	        if (isBlank(ownerFieldsDto.getAddress())) {
242	            missingFields.add("address");
243	        }
244	        if (isBlank(ownerFieldsDto.getCity())) {
245	            missingFields.add("city");
246	        }
247	        if (isBlank(ownerFieldsDto.getTelephone())) {
248	            missingFields.add("telephone");
249	        }
250	        if (!missingFields.isEmpty()) {
251	            throw new InvalidOwnerFieldsException(missingFields);
252	        }
253	    }
254	
255	    private static boolean isBlank(String value) {
256	        return value == null || value.trim().isEmpty();
257	    }
258	
259	    /**
260	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
261	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
262	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
263	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}. The E.164
264	     * string is written back onto the request so it is what gets stored and returned. Any value that
265	     * cannot form a valid E.164 number is rejected with a 400 response whose {@code errors} array
266	     * names {@code telephone}.
267	     */
268	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
269	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
270	    }
271	
272	    /**
273	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
274	     * (400) naming {@code telephone} when it cannot form a valid number.
275	     */
276	    private static String toE164(String telephone) {
277	        if (telephone == null) {
278	            throw new InvalidOwnerFieldsException(List.of("telephone"));
279	        }
280	        boolean hasCountryCode = telephone.trim().startsWith("+");
281	        String digits = telephone.replaceAll("\\D", "");
282	        String national;
283	        if (hasCountryCode) {
284	            national = digits;
285	        } else {
286	            if (digits.startsWith("0")) {
287	                digits = digits.substring(1);
288	            }
289	            national = "61" + digits;
290	        }
291	        if (!national.matches("[0-9]{8,15}")) {
292	            throw new InvalidOwnerFieldsException(List.of("telephone"));
293	        }
294	        return "+" + national;
295	    }
296	
297	    /**
298	     * Rejects creating an owner whose E.164 telephone is already used by any other owner. The
299	     * incoming value has already been converted to its E.164 form by {@link #normalizeTelephone};
300	     * each existing owner's stored telephone is converted the same way before comparison so numbers
301	     * that only differ in formatting still collide. A match results in a 409 response naming
302	     * {@code telephone}.
303	     */
304	    private void rejectDuplicateTelephone(OwnerFieldsDto ownerFieldsDto) {
305	        String telephone = ownerFieldsDto.getTelephone();
306	        for (Owner existing : this.clinicService.findAllOwners()) {
307	            if (telephone.equals(normalizeExisting(existing.getTelephone()))) {
308	                throw new DuplicateOwnerTelephoneException(telephone);
309	            }
310	        }
311	    }
312	
313	    /**
314	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
315	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
316	     */
317	    private static String normalizeExisting(String telephone) {
318	        try {
319	            return toE164(telephone);
320	        } catch (InvalidOwnerFieldsException ex) {
321	            return null;
322	        }
323	    }
324	
325	    /**
326	     * Rejects creating an owner whose {@code lastName} and {@code address} already belong to another
327	     * owner. Both fields are compared case-insensitively and with runs of whitespace collapsed to a
328	     * single space, so values that differ only in letter case or spacing still collide. When the
329	     * request opts in with {@code sharesHousehold} set to {@code true} the check is skipped, allowing
330	     * household members to share a name and address. A match results in a 409 response naming
331	     * {@code lastName} and {@code address}.
332	     */
333	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
334	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
335	            return;
336	        }
337	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
338	        String address = normalizeForComparison(ownerFieldsDto.getAddress());
339	        for (Owner existing : this.clinicService.findAllOwners()) {
340	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
341	                && address.equals(normalizeForComparison(existing.getAddress()))) {
342	                throw new DuplicateOwnerHouseholdException(
343	                    ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
344	            }
345	        }
346	    }
347	
348	    /**
349	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
350	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
351	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
352	     */
353	    private static String normalizeForComparison(String value) {
354	        if (value == null) {
355	            return "";
356	        }
357	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
358	    }
359	
360	    /**
361	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
362	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
363	     * written back onto the request so that is what gets stored and returned. A present but invalid
364	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
365	     */
366	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
367	        String email = ownerFieldsDto.getEmail();
368	        if (email == null) {
369	            return;
370	        }
371	        String trimmed = email.trim();
372	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
373	            throw new InvalidOwnerFieldsException(List.of("email"));
374	        }
375	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
376	    }
377	
378	    /**
379	     * Defaults an owner's {@code registrationDate} on create. When the caller supplies no value,
380	     * it is set to the server's current date so every owner is persisted with a registration date;
381	     * a value provided in the request is kept as-is. The date is stored and returned in ISO
382	     * {@code YYYY-MM-DD} format.
383	     */
384	    private void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
385	        if (ownerFieldsDto.getRegistrationDate() == null) {
386	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
387	        }
388	    }
389	
390	    /**
391	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<LAST3>-<NNNN>'} where
392	     * {@code LAST3} is the upper-cased first three letters of {@code lastName} and {@code NNNN} is a
393	     * global 4-digit zero-padded sequence equal to one more than the current number of owners
394	     * (e.g. {@code 'SMI-0007'}).
395	     */
396	    private void assignCustomerCode(Owner owner) {
397	        String lastName = owner.getLastName();
398	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
399	        int sequence = this.clinicService.findAllOwners().size() + 1;
400	        owner.setCustomerCode(String.format("%s-%04d", prefix, sequence));
401	    }
402	}
